    public MainWindow(){InitializeComponent();try{if(File.Exists(languageFile))lang=File.ReadAllText(languageFile);}catch{}NetworkChange.NetworkAddressChanged+=NetworkChanged;Loaded+=async(_,_)=>{try{api=new();tunnel=new(api);tunnel.Stopped+=()=>Dispatcher.InvokeAsync(()=>{if(screen=="home")ShowHome();});if(api.Token.Length>0){try{await Refresh();}catch(ApiException e) when(e.Status==401||e.Status==403){api.ClearSession();Welcome();}catch{Welcome();}}else Welcome();}catch{MessageBox.Show("Yay VPN could not open secure storage or reach the cloud. Please restart and check your connection.");Close();}};Closed+=(_,_)=>{NetworkChange.NetworkAddressChanged-=NetworkChanged;operation?.Cancel();tunnel?.Dispose();api?.Dispose();};}
