    List<JsonObject> Country(string country)=>nodes.OfType<JsonObject>().Where(n=>n["location"]?.GetValue<string>()==country).ToList();
    void ShowHome(){screen="home";Base("YAY VPN");var countries=nodes.OfType<JsonObject>().Select(n=>n["location"]?.GetValue<string>()??"").Distinct().Order().ToArray();string selected=(picker?.SelectedItem as ComboBoxItem)?.Tag as string??(countries.Contains("Singapore")?"Singapore":countries.FirstOrDefault()??"");picker=new ComboBox{FontSize=19,Padding=new(12),IsEnabled=!tunnel.Connected&&!busy};foreach(var country in countries){var item=new ComboBoxItem{Content=CountryLabel(country),Tag=country};picker.Items.Add(item);if(country==selected)picker.SelectedItem=item;}Root.Children.Add(picker);var expander=new Expander{Header=T("Country pings ▾","国家延迟 ▾","Ping negara ▾"),Foreground=Brushes.White,Margin=new(0,12,0,0)};var list=new StackPanel();foreach(var country in countries){var measured=Country(country).Select(n=>Fresh(n)).Where(n=>n>=0).ToArray();list.Children.Add(new TextBlock{Text=CountryTitle(country)+"   "+(measured.Length>0?measured.Min()+" ms":"—"),Margin=new(6),Foreground=Brushes.White});}expander.Content=list;Root.Children.Add(expander);
        Add(T("Test country pings","测试国家延迟","Uji ping negara"),async()=>{if(busy||tunnel.Connected)return;await Run(async ct=>{await Measure(nodes.OfType<JsonObject>().ToList(),ct);ShowHome();});});
        var hero=new Grid{Height=310};map=new WorldMap{Active=tunnel.Connected};hero.Children.Add(map);power=new Button{Style=(Style)FindResource("PowerButton"),Content="⏻",FontSize=70,Width=180,Height=180,Background=Brushes.Black,Foreground=tunnel.Connected?Green:Red,BorderBrush=tunnel.Connected?Green:Red,BorderThickness=new(2)};power.Click+=async(_,_)=>{if(busy){operation?.Cancel();return;}if(tunnel.Connected){tunnel.Stop();ShowHome();return;}string country=(picker.SelectedItem as ComboBoxItem)?.Tag as string??"";await Run(async ct=>{var group=Country(country);if(group.Any(n=>Fresh(n)<0))await Measure(group,ct);var live=group.Where(n=>Fresh(n)>=0).OrderBy(n=>Fresh(n)).ToList();if(live.Count==0)throw new IOException("No reachable server");long best=Fresh(live[0]);var fast=live.Where(n=>Fresh(n)<=best+Math.Max(10,best/20)).OrderBy(_=>Random.Shared.Next()).ToList();var ordered=fast.Concat(live.Except(fast)).Take(3);Exception? last=null;foreach(var n in ordered){ct.ThrowIfCancellationRequested();try{await tunnel.Connect(n["id"]!.GetValue<string>(),ct);last=null;break;}catch(Exception e){last=e;}}if(last!=null)throw last;ShowHome();});};hero.Children.Add(power);Root.Children.Add(hero);
        status=new TextBlock{Text=tunnel.Connected?T("Connected","已连接","Terhubung"):T("Disconnected","未连接","Terputus"),FontSize=26,TextAlignment=TextAlignment.Center,Foreground=tunnel.Connected?Green:Brushes.White};Root.Children.Add(status);Label(T("TCP ping is a reachability measurement. VPN access is checked separately on connection.","TCP 延迟用于测试可达性，连接时另行验证 VPN 网络访问。","Ping TCP mengukur keterjangkauan. Akses VPN diuji terpisah saat tersambung."),12,Brushes.Gray);Add(T("Refresh locations","刷新地区","Muat ulang lokasi"),async()=>{if(!busy&&!tunnel.Connected)await Run(async _=>await Refresh());});}
    static readonly Dictionary<string,string> CountryCodes=new(){["Singapore"]="SG",["Japan"]="JP",["Hong Kong"]="HK",["United States"]="US",["United Kingdom"]="GB",["Australia"]="AU",["Germany"]="DE",["Spain"]="ES",["Brazil"]="BR",["India"]="IN",["South Africa"]="ZA",["South Korea"]="KR"};
