    static readonly Dictionary<string,(string zh,string id)> Translations=new(){["Singapore"]=("新加坡","Singapura"),["Japan"]=("日本","Jepang"),["Hong Kong"]=("香港","Hong Kong"),["United States"]=("美国","Amerika Serikat"),["United Kingdom"]=("英国","Britania Raya"),["Australia"]=("澳大利亚","Australia"),["Germany"]=("德国","Jerman"),["Spain"]=("西班牙","Spanyol"),["Brazil"]=("巴西","Brasil"),["India"]=("印度","India"),["South Africa"]=("南非","Afrika Selatan"),["South Korea"]=("韩国","Korea Selatan")};
    StackPanel CountryLabel(string country){var panel=new StackPanel{Orientation=Orientation.Horizontal};panel.Children.Add(new FlagView{Code=CountryCodes.GetValueOrDefault(country,""),Width=30,Height=20,Margin=new(0,0,10,0)});panel.Children.Add(new TextBlock{Text=CountryTitle(country),Foreground=Brushes.Black});return panel;}
    long Fresh(JsonObject node){string id=node["id"]!.GetValue<string>();return pings.TryGetValue(id,out var p)&&Environment.TickCount64-p.at<120000&&p.revision==node["revision"]!.GetValue<int>()?p.ms:-1;}
    async Task Measure(List<JsonObject> group,CancellationToken ct){using var gate=new SemaphoreSlim(6);int done=0;await Task.WhenAll(group.Select(async node=>{await gate.WaitAsync(ct);try{long ms=-1;try{var grant=await api.Call("POST","/v1/connect",new(){["server_id"]=node["id"]!.GetValue<string>()},ct);var outbound=grant["config"]!["outbounds"]![0]!;using var socket=new TcpClient();var watch=Stopwatch.StartNew();using var timeout=CancellationTokenSource.CreateLinkedTokenSource(ct);timeout.CancelAfter(1500);await socket.ConnectAsync(outbound["server"]!.GetValue<string>(),outbound["server_port"]!.GetValue<int>(),timeout.Token);ms=Math.Max(1,watch.ElapsedMilliseconds);}catch(ApiException e) when(e.Status==401||e.Status==403){throw;}catch(Exception) when(!ct.IsCancellationRequested){}ct.ThrowIfCancellationRequested();pings[node["id"]!.GetValue<string>()]=(ms,Environment.TickCount64,node["revision"]!.GetValue<int>());if(status!=null)status.Text=$"{++done} / {group.Count}";}finally{gate.Release();}}));}
    async Task Run(Func<CancellationToken,Task> action){busy=true;operation=new();if(picker!=null)picker.IsEnabled=false;try{await action(operation.Token);}catch(OperationCanceledException){tunnel.Stop();}catch{tunnel.Stop();MessageBox.Show(T("Connection failed. Check access or choose another country.","连接失败，请检查账号权限或选择其他国家。","Koneksi gagal. Periksa akses atau pilih negara lain."));}finally{busy=false;operation.Dispose();operation=null;if(screen=="home")ShowHome();}}
